import React, { useEffect, useState } from 'react';
import { ProfileInfo } from '@backstage/core-plugin-api';

import staticData from '../../helpers/data.json';

import { blue } from '@material-ui/core/colors';
import TreeView from '@material-ui/lab/TreeView';
import TreeItem from '@material-ui/lab/TreeItem';
import { Card, Divider, Typography, CardContent, } from '@material-ui/core';

import BookIcon from '@material-ui/icons/Book';
import AddCircleIcon from '@material-ui/icons/AddCircle';
import ExpandMoreIcon from '@material-ui/icons/ExpandMore';
import DocumentIcon from '@material-ui/icons/InsertDriveFile';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import BookmarkBorderIcon from '@material-ui/icons/BookmarkBorder';
import ImportContactsIcon from '@material-ui/icons/ImportContacts';

import { CreateProjectDialog } from '../CreateProjectDialog/CreateProjectDialogComponent';

import { createProject, getProjects, getUserProjects } from '../../helpers/chatService';

export const ProjectsComponent = ({ onChangeProject, projectId, profile }: { onChangeProject: (codigo: number) => void, projectId: number, profile: ProfileInfo }) => {
  const [open, setOpen] = useState(false);
  const [_, setProjects] = useState<any[]>([]);
  const [userProjects, setUserProjects] = useState<any[]>([]);
  const [nombreProyecto, setProjectName] = useState('');
  const [descripcionProyecto, setProjectDescription] = useState('');

  const fetchUserProjects = async () => {
    const newProjects = await getUserProjects(profile.email!)
    setUserProjects(newProjects);
  };

  const fetchProjects = async () => {
    const allProjects = await getProjects();
    setProjects(allProjects);
  }

  const handleClickOpenDialog = () => {
    setOpen(true);
  };

  useEffect(() => {
    if (profile.email) {
      fetchUserProjects();
      fetchProjects();
    }
  }, [profile]);

  const handleClose = () => {
    setOpen(false);
  };

  const handleItemClick = (codigo: number) => {
    onChangeProject(codigo);
  };

  const onCreateProject = async (newProject: any) => {
    const resp = await createProject(newProject);
    setUserProjects([...userProjects, resp]);
    onChangeProject(resp.id);
  }

  const handleCrearProyecto = () => {
    const nuevoProyecto = {
      name: nombreProyecto,
      username: profile.email,
      description: descripcionProyecto,
    };
    onCreateProject(nuevoProyecto);

    setProjectName('');
    setProjectDescription('');
    handleClose();
  };

  interface RenderTree {
    id: string;
    name: string;
    type: string;
    children?: RenderTree[];
  }

  const [selectedNodeId, setSelectedNodeId] = useState<string>();

  const isActive = (node: RenderTree): Boolean => {
    if (node.id === selectedNodeId) {
      return true;
    }
    if (node.children) {
      return node.children.some((child: RenderTree) => isActive(child));
    }
    return false;
  };

  const renderTree = (nodes: RenderTree[]) => {

    const getIcon = (nodeType: string) => {
      switch (nodeType) {
        case 'project':
          return <BookmarkBorderIcon />;
        case 'epic':
          return <BookIcon />;
        case 'feature':
          return <ImportContactsIcon />;
        case 'story':
          return <DocumentIcon />;
        default:
          return null;
      }
    };

    const getColor = (node: RenderTree) => {
      if (isActive(node)) {
        switch (node.type) {
          case 'project':
            return '#58b757';
          case 'epic':
            return '#e39348';
          case 'feature':
            return '#4973ce';
          default:
            return '#9042fd';
        }
      } else {
        return 'grey';
      }
    };

    const handleNodeSelect = (node: RenderTree) => {
      if (node.type === 'story') {
        setSelectedNodeId(node.id);
      }
    };

    return nodes.map((node: RenderTree) => (
      <TreeItem
        key={node.id}
        nodeId={node.id}
        label={
          <div
            style={{ color: getColor(node) }}
            onClick={() => handleNodeSelect(node)}
          >
            <span style={{ marginRight: '8px' }}>{getIcon(node.type)}</span>
            {node.name}
          </div>
        }
      >
        {Array.isArray(node.children) ? renderTree(node.children) : null}
      </TreeItem>
    ))
  };

  return (
    <>
      <Card style={{ minHeight: '25rem', maxHeight: '50rem' }}>
        <CardContent>
          <Typography variant="h4" style={{ color: '#2e77d0' }}>
            <AddCircleIcon
              style={{
                color: blue[500],
                marginRight: '10px',
                cursor: 'pointer',
              }}
              onClick={handleClickOpenDialog}
            />
            Proyectos
          </Typography>
          <Divider />
          {userProjects.length === 0 ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
              }}
            >
              <Typography variant="body2">
                Este es un asistente virtual que te ayudará a resolver tus dudas
                técnicas.
              </Typography>
            </div>
          ) : (
            <TreeView
              defaultCollapseIcon={<ExpandMoreIcon />}
              defaultExpandIcon={<ChevronRightIcon />}
            >
              {renderTree(staticData)}
            </TreeView>

          )}
        </CardContent>
      </Card>

      <CreateProjectDialog
        open={open}
        projectName={nombreProyecto}
        projectDescription={descripcionProyecto}
        handleClose={handleClose}
        handleCrearProyecto={handleCrearProyecto}
        setProjectName={setProjectName}
        setProjectDescription={setProjectDescription}
      />
    </>
  );
};


Lo que necesito es que simules la logica de los nodos, que se pinte de un color todos los padres del nodo seleccionado
Para adaptar la lógica de los nodos y la funcionalidad de selección de nodos del componente de React al componente de Angular, podemos hacer lo siguiente:

1. Añadir una estructura de datos para los nodos.
2. Implementar la lógica para seleccionar un nodo y cambiar el color de los nodos padres.
3. Actualizar la plantilla HTML para reflejar la estructura de los nodos y aplicar los estilos correspondientes.

