import { DOCUMENT } from "@angular/common";
import { FormsModule } from "@angular/forms";
import { RouterModule } from "@angular/router";
import { ChangeDetectionStrategy, Component, inject } from "@angular/core";

import { InputSwitchModule } from "primeng/inputswitch";

interface MenuItem {
  icon: string;
  label: string;
  routerLink: string[];
  type: string;
  children?: MenuItem[];
}

@Component({
  selector: "app-sidebar",
  standalone: true,
  imports: [RouterModule, InputSwitchModule, FormsModule],
  templateUrl: "./sidebar.component.html",
  styleUrls: ["./sidebar.component.css"],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SidebarComponent {
  #document = inject(DOCUMENT);
  isDarkMode = true;
  selectedNodeId: string | null = null;

  menuItems: MenuItem[] = [
    {
      icon: "pi pi-home",
      label: "Dashboard",
      routerLink: ["/"],
      type: "project",
    },
    {
      icon: "pi pi-bookmark",
      label: "Bookmarks",
      routerLink: ["/bookmarks"],
      type: "epic",
      children: [
        {
          icon: "pi pi-users",
          label: "Team",
          routerLink: ["/team"],
          type: "feature",
          children: [
            {
              icon: "pi pi-comments",
              label: "Messages",
              routerLink: ["/messages"],
              type: "story",
            },
          ],
        },
      ],
    },
    {
      icon: "pi pi-calendar",
      label: "Calendar",
      routerLink: ["/calendar"],
      type: "project",
    },
  ];

  toggleLightDark() {
    const linkElement = this.#document.getElementById(
      "app-theme"
    ) as HTMLLinkElement;
    if (linkElement.href.includes("light")) {
      linkElement.href = "dark.css";
      this.isDarkMode = true;
    } else {
      linkElement.href = "light.css";
      this.isDarkMode = false;
    }
  }

  isActive(node: MenuItem): boolean {
    if (node.routerLink.join('') === this.selectedNodeId) {
      return true;
    }
    if (node.children) {
      return node.children.some((child) => this.isActive(child));
    }
    return false;
  }

  getColor(node: MenuItem): string {
    if (this.isActive(node)) {
      switch (node.type) {
        case "project":
          return "#58b757";
        case "epic":
          return "#e39348";
        case "feature":
          return "#4973ce";
        default:
          return "#9042fd";
      }
    } else {
      return "grey";
    }
  }

  handleNodeSelect(node: MenuItem) {
    if (node.type === "story") {
      this.selectedNodeId = node.routerLink.join('');
    }
  }
}
